using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.ComponentModel;
namespace RAWSelectionAssistant.Views;
public partial class PhotoGradePageView
{
 private Window? r53MultiWindow;
 private async void R53MultiCompare(object sender,RoutedEventArgs e)
 {
  if(model is null)return;var workspace=model;var select=new ListBox{ItemsSource=model.R53Variants,DisplayMemberPath="Name",SelectionMode=SelectionMode.Multiple,Height=130};foreach(var v in model.R53Variants.Take(2))select.SelectedItems.Add(v);
  var root=new DockPanel{Margin=new Thickness(12)};var button=new Button{Content="对比所选2–4个变体"};var close=new Button{Content="退出对比"};var status=new TextBlock();var bar=new StackPanel{Orientation=Orientation.Horizontal};bar.Children.Add(button);bar.Children.Add(close);bar.Children.Add(status);DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);DockPanel.SetDock(select,Dock.Top);root.Children.Add(select);var grid=new Grid();root.Children.Add(grid);var views=new List<ColorStudioImageViewport>();var slots=new Dictionary<Guid,(ContentControl Slot,string Name)>();bool syncing=false,closed=false;Point? pan=null;long request=0;
  void RenderFrames(){if(closed)return;status.Text=workspace.R53MultiCompareStatus;foreach(var frame in workspace.R53CompareFrames){if(!slots.TryGetValue(frame.Id,out var slot)||slot.Slot.Content is ColorStudioImageViewport)continue;var view=new ColorStudioImageViewport{Original=frame.Image,Mode="原片",SourcePixelSize=new Size(frame.Image.PixelWidth,frame.Image.PixelHeight)};slots[frame.Id].Slot.Content=view;views.Add(view);view.State.Changed+=(_,_)=>{if(syncing)return;syncing=true;try{foreach(var other in views.Where(v=>v!=view))other.State.Follow(view.State);}finally{syncing=false;}};view.MouseWheel+=(_,args)=>{view.State.ZoomAbout(args.GetPosition(view),args.Delta>0?1.15:1/1.15);args.Handled=true;};view.MouseLeftButtonDown+=(_,args)=>{pan=args.GetPosition(view);view.CaptureMouse();};view.MouseMove+=(_,args)=>{if(pan is{} start&&args.LeftButton==MouseButtonState.Pressed){var next=args.GetPosition(view);view.State.PanBy(next-start);pan=next;}};view.MouseLeftButtonUp+=(_,_)=>{pan=null;view.ReleaseMouseCapture();};}}
  PropertyChangedEventHandler changed=(_,args)=>{if(args.PropertyName is nameof(workspace.R53CompareFrames) or nameof(workspace.R53MultiCompareStatus))RenderFrames();};workspace.PropertyChanged+=changed;
  async void Prepare(){var current=++request;try{var variants=select.SelectedItems.Cast<RAWSelectionAssistant.Core.Services.Projects.StudioEditVersion>().ToArray();grid.Children.Clear();grid.RowDefinitions.Clear();grid.ColumnDefinitions.Clear();views.Clear();slots.Clear();grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new());grid.RowDefinitions.Add(new());if(variants.Length>2)grid.RowDefinitions.Add(new());for(int i=0;i<variants.Length;i++){var panel=new DockPanel();var label=new TextBlock{Text=variants[i].Name};DockPanel.SetDock(label,Dock.Top);panel.Children.Add(label);var slot=new ContentControl{Content=new TextBlock{Text="正在载入…",HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center}};panel.Children.Add(slot);Grid.SetColumn(panel,i%2);Grid.SetRow(panel,i/2);grid.Children.Add(panel);slots[variants[i].Id]=(slot,variants[i].Name);}await workspace.PrepareR53VariantComparisonAsync(variants.Select(v=>v.Id).ToArray());if(!closed&&current==request)RenderFrames();}catch(Exception error)when(error is ArgumentException or InvalidOperationException or System.IO.IOException or NotSupportedException){status.Text="对比未完成："+error.Message;}}
  var window=new Window{Title="光镜 · 变体同步对比",Owner=Window.GetWindow(this),Width=1100,Height=780,Content=root,Background=Background};r53MultiWindow?.Close();r53MultiWindow=window;button.Click+=(_,_)=>Prepare();close.Click+=(_,_)=>window.Close();window.Closed+=(_,_)=>{closed=true;request++;workspace.PropertyChanged-=changed;workspace.CloseR53VariantComparison();if(r53MultiWindow==window)r53MultiWindow=null;};window.Show();await Task.Yield();if(!closed)Prepare();
 }
}
